SET NOCOUNT ON;
SELECT 'TableExists' CheckName,CASE WHEN OBJECT_ID(N'dbo.UserSessions',N'U') IS NULL THEN 1 ELSE 0 END FindingCount;
SELECT 'ExactColumns' CheckName,CASE WHEN (SELECT COUNT(*) FROM sys.columns WHERE object_id=OBJECT_ID(N'dbo.UserSessions'))=15 THEN 0 ELSE 1 END FindingCount;
SELECT 'ExpectedTypesAndNullability' CheckName,CASE WHEN COL_LENGTH(N'dbo.UserSessions',N'SessionId')=16 AND COL_LENGTH(N'dbo.UserSessions',N'CurrentAccessJti')=16 AND COL_LENGTH(N'dbo.UserSessions',N'RevocationReason')=32 AND COLUMNPROPERTY(OBJECT_ID(N'dbo.UserSessions'),N'RowVer',N'ColumnId') IS NOT NULL THEN 0 ELSE 1 END FindingCount;
SELECT 'PrimaryKey' CheckName,CASE WHEN EXISTS(SELECT 1 FROM sys.key_constraints WHERE parent_object_id=OBJECT_ID(N'dbo.UserSessions') AND name=N'PK_UserSessions' AND type=N'PK') THEN 0 ELSE 1 END FindingCount;
SELECT 'UniqueIdentifiers' CheckName,CASE WHEN (SELECT COUNT(*) FROM sys.key_constraints WHERE parent_object_id=OBJECT_ID(N'dbo.UserSessions') AND name IN(N'UQ_UserSessions_SessionId',N'UQ_UserSessions_CurrentAccessJti'))=2 THEN 0 ELSE 1 END FindingCount;
SELECT 'TrustedForeignKeys' CheckName,COUNT(*) FindingCount FROM sys.foreign_keys WHERE parent_object_id=OBJECT_ID(N'dbo.UserSessions') AND (is_disabled=1 OR is_not_trusted=1 OR name NOT IN(N'FK_UserSessions_Client',N'FK_UserSessions_UserTenant',N'FK_UserSessions_InstanceTenant'));
SELECT 'ExpectedForeignKeyCount' CheckName,CASE WHEN (SELECT COUNT(*) FROM sys.foreign_keys WHERE parent_object_id=OBJECT_ID(N'dbo.UserSessions'))=3 THEN 0 ELSE 1 END FindingCount;
SELECT 'ClosedClientType' CheckName,CASE WHEN EXISTS(SELECT 1 FROM sys.check_constraints WHERE parent_object_id=OBJECT_ID(N'dbo.UserSessions') AND name=N'CK_UserSessions_ClientType' AND definition LIKE '%DESKTOP%' AND definition LIKE '%WEB%' AND definition LIKE '%MOBILE%') THEN 0 ELSE 1 END FindingCount;
SELECT 'LifecycleConstraints' CheckName,CASE WHEN (SELECT COUNT(*) FROM sys.check_constraints WHERE parent_object_id=OBJECT_ID(N'dbo.UserSessions') AND name IN(N'CK_UserSessions_Expiry',N'CK_UserSessions_Refresh',N'CK_UserSessions_Revocation',N'CK_UserSessions_InstanceClient'))=4 THEN 0 ELSE 1 END FindingCount;
SELECT 'ExpectedIndex' CheckName,CASE WHEN EXISTS(SELECT 1 FROM sys.indexes WHERE object_id=OBJECT_ID(N'dbo.UserSessions') AND name=N'IX_UserSessions_TenantUserIssued') THEN 0 ELSE 1 END FindingCount;
SELECT 'RowVersion' CheckName,CASE WHEN EXISTS(SELECT 1 FROM sys.columns WHERE object_id=OBJECT_ID(N'dbo.UserSessions') AND name=N'RowVer' AND system_type_id=189 AND is_nullable=0) THEN 0 ELSE 1 END FindingCount;
SELECT 'StrictRlsCount' CheckName,CASE WHEN (SELECT COUNT(*) FROM sys.security_predicates WHERE target_object_id=OBJECT_ID(N'dbo.UserSessions') AND predicate_definition COLLATE DATABASE_DEFAULT LIKE '%fn_FilterByTenant%' AND predicate_definition COLLATE DATABASE_DEFAULT NOT LIKE '%OrGlobal%')=3 THEN 0 ELSE 1 END FindingCount;
SELECT 'FilterPredicate' CheckName,CASE WHEN EXISTS(SELECT 1 FROM sys.security_predicates WHERE target_object_id=OBJECT_ID(N'dbo.UserSessions') AND predicate_type_desc=N'FILTER') THEN 0 ELSE 1 END FindingCount;
SELECT 'InsertBlock' CheckName,CASE WHEN EXISTS(SELECT 1 FROM sys.security_predicates WHERE target_object_id=OBJECT_ID(N'dbo.UserSessions') AND operation_desc=N'AFTER INSERT') THEN 0 ELSE 1 END FindingCount;
SELECT 'UpdateBlock' CheckName,CASE WHEN EXISTS(SELECT 1 FROM sys.security_predicates WHERE target_object_id=OBJECT_ID(N'dbo.UserSessions') AND operation_desc=N'AFTER UPDATE') THEN 0 ELSE 1 END FindingCount;
SELECT 'NoOverlay' CheckName,COUNT(*) FindingCount FROM sys.security_predicates WHERE target_object_id=OBJECT_ID(N'dbo.UserSessions') AND predicate_definition COLLATE DATABASE_DEFAULT LIKE '%OrGlobal%';
SELECT 'NoSeedRows' CheckName,COUNT(*) FindingCount FROM dbo.UserSessions;
SELECT 'PriorPhaseTablesIntact' CheckName,(CASE WHEN OBJECT_ID(N'dbo.ApplicationInstances',N'U') IS NULL THEN 1 ELSE 0 END)+(CASE WHEN OBJECT_ID(N'dbo.AdministrativeReadAuditLog',N'U') IS NULL THEN 1 ELSE 0 END) FindingCount;
